import { isPositiveSafeInteger, namespaceWorkflowNodes, validateNodeId } from "./validation.js";
import { INVALID_ARGUMENT } from "../../errors/index.js";
/** Default maximum number of loop iterations */
const DEFAULT_MAX_ITERATIONS = 10;
/** Absolute upper bound on loop iterations to prevent runaway loops */
const MAX_ITERATIONS_LIMIT = 100;
/** Create a loop workflow step. */
export function loop(id, options) {
    validateNodeId(id);
    if (typeof options.while !== "function") {
        throw INVALID_ARGUMENT.create({
            detail: `Loop "${id}" must have a 'while' condition function`,
        });
    }
    if (!options.steps) {
        throw INVALID_ARGUMENT.create({ detail: `Loop "${id}" must have 'steps' configured` });
    }
    const maxIterations = options.maxIterations ?? DEFAULT_MAX_ITERATIONS;
    if (!isPositiveSafeInteger(maxIterations)) {
        if (typeof maxIterations === "number" && maxIterations < 1) {
            throw INVALID_ARGUMENT.create({ detail: `Loop "${id}" maxIterations must be at least 1` });
        }
        throw INVALID_ARGUMENT.create({
            detail: `Loop "${id}" maxIterations must be an integer between 1 and 100`,
        });
    }
    if (maxIterations > MAX_ITERATIONS_LIMIT) {
        throw INVALID_ARGUMENT.create({
            detail: `Loop "${id}" maxIterations cannot exceed ${MAX_ITERATIONS_LIMIT} (got ${maxIterations}). ` +
                `For higher limits, consider restructuring your workflow.`,
        });
    }
    return {
        id,
        config: {
            type: "loop",
            description: options.description,
            while: options.while,
            steps: Array.isArray(options.steps)
                ? namespaceWorkflowNodes(`${id}/`, options.steps)
                : options.steps,
            maxIterations,
            onMaxIterations: options.onMaxIterations,
            onComplete: options.onComplete,
            checkpoint: options.checkpoint ?? true,
            retry: options.retry,
            timeout: options.timeout,
            iterationTimeout: options.iterationTimeout,
            skip: options.skip,
            delay: options.delay,
        },
    };
}
/** Create a do-while workflow loop. */
export function doWhile(id, options) {
    const { until, ...rest } = options;
    if (typeof until !== "function") {
        throw INVALID_ARGUMENT.create({
            detail: `Loop "${id}" must have an 'until' condition function`,
        });
    }
    return loop(id, {
        ...rest,
        while: async (ctx, loopCtx) => {
            if (loopCtx.isFirstIteration)
                return true;
            return !(await until(ctx, loopCtx));
        },
    });
}
/** Create a fixed-count workflow loop. */
export function times(id, count, steps, options) {
    return loop(id, {
        ...options,
        maxIterations: count,
        while: (_, loopCtx) => loopCtx.iteration < count,
        steps,
    });
}
